LESSONS.push(
/* ---------- M9 SAVOLLAR ---------- */
{id:"questions",line:"ques",t:"Savol tuzish",s:"Yordamchi fe'l oldinga chiqadi",
idea:"Inglizcha savolning siri bitta: <b>yordamchi fe'l eganing oldiga sakrab o'tadi</b>. “You are happy” → “Are you happy?” Agar gapda yordamchi fe'l bo'lmasa, <b>do, does, did</b> yordamga keladi. So'roq so'z (what, where, when) bo'lsa, u eng boshida turadi. Bitta istisno: savol eganing o'ziga berilsa (Kim keldi?), tartib o'zgarmaydi.",
f:{p:"o:(Wh-so'z)|a:Yordamchi fe'l|S|v:Asosiy fe'l|o:?",n:"a:Who / What|v:fe'l|o:... ? (egaga savol)"},
use:[["Ha / yo'q savoli","{a:Do} {s:you} {v:like} tea?","Siz choyni yoqtirasizmi?"],["Wh-savol","Where {a:does} {s:she} {v:live}?","U qayerda yashaydi?"],["Egaga savol: do kerak emas","{s:Who} {v:lives} here?","Bu yerda kim yashaydi?"],["Predlog oxirida qoladi","What {a:are} {s:you} {v:looking} at?","Siz nimaga qarayapsiz?"],["Bilvosita savolda darak tartibi","Can you tell me where {s:the bank} {v:is}?","Bank qayerdaligini ayta olasizmi?"]],
err:[["Where you live?","Where do you live?","Yordamchi fe'l do kerak."],["Who did come?","Who came?","Egaga savolda did ishlatilmaydi."],["Do you know where is he?","Do you know where he is?","Bilvosita savolda darak tartibi."]],
ex:[["mc","Where ___ your brother work?",["do","does","is"],1,"Your brother = he: does."],
["mc","Who ___ this picture?",["did paint","painted","did painted"],1,"Egaga savol: did yo'q."],
["ord","What time does the lesson start?","Dars soat nechada boshlanadi?"],
["mc","Could you tell me where ___?",["is the station","the station is","does the station"],1,"Bilvosita savol: darak tartibi."],
["in","___ did you go last night? To the cinema.",["where"],"Joy so'raladi: Where."],
["ord","How long have you lived here?","Siz bu yerda qachondan beri yashaysiz?"]]},

{id:"tag-questions",line:"ques",t:"Tag questions",s:"Shunday emasmi?",
idea:"Gap oxiriga qo'shiladigan kichik “dumcha” savol: “Havo yaxshi, <b>shunday emasmi?</b>” Qoida oyna kabi: gap <b>ijobiy</b> bo'lsa dumcha <b>inkor</b>, gap inkor bo'lsa dumcha ijobiy. Dumchada gapdagi yordamchi fe'l va olmosh takrorlanadi.",
f:{p:"o:Ijobiy gap ,|a:yordamchi fe'l + n't|S|o:?",n:"o:Inkor gap ,|a:yordamchi fe'l|S|o:?"},
use:[["Ijobiy gap, inkor dumcha","It is cold, {a:isn't} {s:it}?","Sovuq, shunday emasmi?"],["Inkor gap, ijobiy dumcha","You don't smoke, {a:do} {s:you}?","Siz chekmaysiz, to'g'rimi?"],["Yordamchi fe'l bo'lmasa do / does / did","She works here, {a:doesn't} {s:she}?","U shu yerda ishlaydi, shundaymi?"],["Maxsus holatlar","I am late, {a:aren't} {s:I}? / Let's go, {a:shall} {s:we}?","Kech qoldim, a? / Ketdik, xo'pmi?"]],
err:[["She is a doctor, is she?","She is a doctor, isn't she?","Ijobiy gapga inkor dumcha."],["You like tea, aren't you?","You like tea, don't you?","Like oddiy fe'l: do."]],
ex:[["mc","You are a student, ___?",["are you","aren't you","don't you"],1,"Ijobiy gap: aren't you."],
["mc","He can't swim, ___?",["can he","can't he","does he"],0,"Inkor gap: can he."],
["mc","They went home, ___?",["weren't they","didn't they","did they"],1,"Past Simple: didn't they."],
["in","She has finished, ___ she?",["hasn't"],"Has → hasn't."],
["mc","Let's have a break, ___?",["will we","shall we","don't we"],1,"Let's bilan shall we."]]},

/* ---------- M10 GERUND VA INFINITIVE ---------- */
{id:"gerund-inf",line:"verb",t:"Gerund yoki Infinitive?",s:"-ing yoki to",
idea:"Ikki fe'l yonma-yon kelsa, ikkinchisi yo <b>-ing</b> oladi, yo <b>to</b> bilan keladi. Buni birinchi fe'l hal qiladi. Sodda yordamchi qoida: <b>yoqtirish va tugatish</b> fe'llaridan keyin ko'pincha -ing (enjoy, finish, avoid, mind), <b>xohish va reja</b> fe'llaridan keyin to (want, decide, hope, plan). Predlogdan keyin esa <b>doim -ing</b>.",
f:{p:"a:enjoy, finish, mind, avoid, keep, suggest|v:V-ing",n:"a:want, decide, hope, plan, need, promise, learn|v:to V1"},
use:[["Fe'l + -ing","{s:I} {a:enjoy} {v:reading}.","Men o'qishni yoqtiraman."],["Fe'l + to","{s:She} {a:decided} {v:to leave}.","U ketishga qaror qildi."],["Predlogdan keyin -ing","{s:He} is good at {v:drawing}.","U rasm chizishga usta."],["Ega vazifasida -ing","{v:Swimming} is good for you.","Suzish foydali."],["Ma'no o'zgaradi: stop","He stopped {v:smoking}. / He stopped {v:to smoke}.","U chekishni tashladi. / U chekish uchun to'xtadi."]],
err:[["I enjoy to read.","I enjoy reading.","Enjoy dan keyin -ing."],["I want going home.","I want to go home.","Want dan keyin to."],["I'm interested in learn English.","I'm interested in learning English.","Predlogdan keyin -ing."]],
ex:[["mc","She enjoys ___ films.",["watch","to watch","watching"],2,"Enjoy + V-ing."],
["mc","We decided ___ a new car.",["buying","to buy","buy"],1,"Decide + to V1."],
["in","I'm tired of ___ (wait).",["waiting"],"Predlog (of) dan keyin -ing."],
["mc","Would you mind ___ the door?",["to close","closing","close"],1,"Mind + V-ing."],
["mc","He promised ___ late.",["not being","not to be","to not being"],1,"Promise + (not) to V1."],
["in","I hope ___ (see) you soon.",["to see"],"Hope + to V1."]]},

/* ---------- M11 OT VA ARTIKL ---------- */
{id:"articles",line:"noun",t:"Artikllar: a, an, the",s:"Qaysi biri? Istalgan birimi yoki aynan o'shami",
idea:"O'zbek tilida artikl yo'q, shuning uchun bu mavzu qiyin tuyuladi. Sodda qoida: narsa haqida <b>birinchi marta</b> gapirsangiz yoki u <b>istalgan bittasi</b> bo'lsa, <b>a / an</b> (“bir”). Tinglovchi <b>aynan qaysi narsa</b> ekanini bilsa, <b>the</b> (“o'sha”). Unli tovush oldidan an: an apple, an hour.",
f:{p:"a:a / an|o:birinchi marta, istalgan bittasi, kasb",n:"a:the|o:aynan o'sha, yagona narsa, ikkinchi marta",q:"a:artiklsiz|o:umumiy ma'no, ko'plik, shahar va davlatlar"},
use:[["Birinchi marta a, keyin the","I saw {a:a} dog. {a:The} dog was big.","Men it ko'rdim. O'sha it katta edi."],["Kasb bilan a / an","She is {a:a} teacher.","U o'qituvchi."],["Yagona narsalar bilan the","{a:The} sun is hot.","Quyosh issiq."],["Umumiy ma'noda artiklsiz","I like music. Cats are clever.","Men musiqani yoqtiraman. Mushuklar aqlli."],["Unli tovush oldidan an","{a:an} apple, {a:an} hour, lekin {a:a} university","Harf emas, tovush muhim."]],
err:[["She is teacher.","She is a teacher.","Kasb oldidan a / an."],["I love the music.","I love music.","Umumiy ma'noda the kerak emas."],["He lives in the Tashkent.","He lives in Tashkent.","Shahar nomlari artiklsiz."]],
ex:[["mc","My father is ___ engineer.",["a","an","the"],1,"Engineer unli tovush bilan boshlanadi."],
["mc","Can you close ___ door, please?",["a","an","the"],2,"Qaysi eshik ekani ma'lum."],
["mc","I bought a book and a pen. ___ book was expensive.",["A","The","An"],1,"Ikkinchi marta: the."],
["mc","___ moon goes round the earth.",["A","The","(artiklsiz)"],1,"Yagona narsa: the."],
["mc","She plays ___ tennis every week.",["a","the","(artiklsiz)"],2,"Sport turlari artiklsiz."],
["mc","It takes ___ hour to get there.",["a","an","the"],1,"Hour so'zida h o'qilmaydi: an hour."]]},

{id:"countable",line:"noun",t:"Sanaladigan va sanalmaydigan otlar",s:"Some, any, much, many, few, little",
idea:"Olmani sanash mumkin: bitta olma, ikkita olma. Suvni esa sanab bo'lmaydi: “ikkita suv” demaymiz. Inglizchada bu farq juda muhim, chunki <b>miqdor so'zlari shunga qarab tanlanadi</b>. Sanaladiganlar bilan <b>many, a few</b>, sanalmaydiganlar bilan <b>much, a little</b>. Sanalmaydigan otlar ko'plik -s olmaydi: water, money, information, advice.",
f:{p:"a:many, a few, few|o:+ sanaladigan ko'plik (books)",n:"a:much, a little, little|o:+ sanalmaydigan (water)",q:"a:some (darak), any (savol va inkor), a lot of|o:+ ikkalasi ham"},
use:[["Darak gapda some","I have {a:some} money.","Menda biroz pul bor."],["Savol va inkorda any","Do you have {a:any} questions?","Savollaringiz bormi?"],["Sanaladigan: many, sanalmaydigan: much","How {a:many} books? How {a:much} water?","Nechta kitob? Qancha suv?"],["A few / a little: oz, lekin yetarli","I have {a:a few} friends and {a:a little} time.","Bir necha do'stim va biroz vaqtim bor."],["Few / little (a siz): deyarli yo'q","He has {a:little} money.","Uning puli deyarli yo'q."]],
err:[["How much books do you have?","How many books do you have?","Books sanaladi: many."],["She gave me an advice.","She gave me some advice.","Advice sanalmaydi."],["I don't have some money.","I don't have any money.","Inkorda any."]],
ex:[["mc","How ___ sugar do you want?",["many","much","few"],1,"Sugar sanalmaydi."],
["mc","There aren't ___ eggs in the fridge.",["some","any","much"],1,"Inkor: any."],
["mc","I have ___ friends in Tashkent.",["a little","a few","much"],1,"Friends sanaladi: a few."],
["in","How ___ people were at the party?",["many"],"People sanaladigan ko'plik."],
["mc","Can I have ___ water, please?",["some","any","many"],0,"Iltimos va taklifda some."],
["mc","Qaysi so'z sanalmaydi?",["chair","information","apple"],1,"Information ko'plikda ishlatilmaydi."]]},

/* ---------- M12 SIFAT VA RAVISH ---------- */
{id:"comparison",line:"adj",t:"Sifat darajalari",s:"Kattaroq va eng katta",
idea:"Ikki narsani solishtirsak <b>-er</b> yoki <b>more</b>, ko'pchilik ichidan eng zo'rini aytsak <b>-est</b> yoki <b>most</b>. Qaysi biri ekanini so'zning uzunligi hal qiladi: <b>qisqa so'zga qo'shimcha</b> (tall → taller), <b>uzun so'zga alohida so'z</b> (beautiful → more beautiful). Uchta mashhur istisno: good → better → best, bad → worse → worst, far → further.",
f:{p:"a:qisqa sifat + er|o:+ than   (taller than)",n:"a:more + uzun sifat|o:+ than   (more expensive than)",q:"a:the + sifat + est  /  the most + sifat|o:(the tallest, the most expensive)"},
use:[["Qisqa sifat","Ali is {v:taller} than Vali.","Ali Validan balandroq."],["Uzun sifat","This phone is {v:more expensive} than that one.","Bu telefon unisidan qimmatroq."],["Orttirma daraja","She is {a:the} {v:best} student in the class.","U sinfdagi eng yaxshi o'quvchi."],["Tenglik: as ... as","He is {a:as} tall {a:as} his father.","U otasi kabi baland."],["-y bilan tugasa: y → ier","happy → {v:happier} → the {v:happiest}","baxtli → baxtliroq → eng baxtli"]],
err:[["She is more tall than me.","She is taller than me.","Qisqa sifatga -er."],["This is the most good film.","This is the best film.","Good → better → best."],["He is taller that me.","He is taller than me.","Qiyoslashda than."]],
ex:[["mc","My house is ___ than yours.",["big","bigger","the biggest"],1,"Qiyosiy daraja: bigger."],
["mc","This is ___ book I have ever read.",["more interesting","the most interesting","most interesting"],1,"Orttirma: the most."],
["in","Today is ___ (hot) than yesterday.",["hotter"],"Qisqa sifat, undosh ikkilanadi: hotter."],
["in","He is the ___ (good) player in the team.",["best"],"Good → best."],
["mc","She is as ___ as her sister.",["taller","tall","tallest"],1,"As + oddiy daraja + as."],
["mc","My result was ___ than last time.",["badder","worse","worst"],1,"Bad → worse."]]},

{id:"adverbs",line:"adj",t:"Sifat yoki ravish?",s:"Qanday narsa, qanday qilib",
idea:"<b>Sifat</b> narsaning qandayligini aytadi (a slow car), <b>ravish</b> ish qanday bajarilganini aytadi (he drives slowly). Ko'pincha sifatga <b>-ly</b> qo'shsangiz ravish hosil bo'ladi. Savol bering: “qanday narsa?” bo'lsa sifat, “qanday qilib?” bo'lsa ravish. Be, look, feel, seem dan keyin esa sifat turadi.",
f:{p:"a:sifat|o:+ ot   (a careful driver)",n:"v:fe'l|a:+ ravish (-ly)|o:  (drives carefully)",q:"a:too + sifat|o:(haddan ortiq)   /|a:sifat + enough|o:(yetarli)"},
use:[["Sifat otni tasvirlaydi","She is a {a:careful} driver.","U ehtiyotkor haydovchi."],["Ravish fe'lni tasvirlaydi","She drives {a:carefully}.","U ehtiyotkorlik bilan haydaydi."],["Istisnolar: good → well, fast → fast, hard → hard","He speaks English {a:well}.","U inglizcha yaxshi gapiradi."],["Hard va hardly farqi","He works {a:hard}. / He {a:hardly} works.","U qattiq ishlaydi. / U deyarli ishlamaydi."],["Too va enough","It is {a:too} cold. / It is warm {a:enough}.","Haddan ortiq sovuq. / Yetarlicha iliq."]],
err:[["He speaks English good.","He speaks English well.","Fe'lni ravish tasvirlaydi: well."],["She sings beautiful.","She sings beautifully.","Qanday kuylaydi: -ly."],["You look happily.","You look happy.","Look dan keyin sifat."]],
ex:[["mc","He ran very ___.",["quick","quickly","quicker"],1,"Qanday yugurdi: ravish."],
["mc","She speaks English very ___.",["good","well","goodly"],1,"Good ning ravishi: well."],
["mc","This soup tastes ___.",["good","well","goodly"],0,"Taste dan keyin sifat."],
["in","Please drive ___ (careful).",["carefully"],"Careful + ly."],
["mc","I'm not tall ___ to play basketball.",["too","enough","very"],1,"Sifat + enough."],
["mc","He works very ___. He never rests.",["hard","hardly","harder"],0,"Hard o'zgarmaydi."]]},

/* ---------- M13 PREDLOGLAR ---------- */
{id:"prep-time",line:"prep",t:"Vaqt predloglari: in, on, at",s:"Katta, o'rta, kichik",
idea:"Uchta predlogni <b>uch o'lchamdagi quti</b> deb tasavvur qiling. <b>IN</b> eng katta quti: oy, yil, fasl, asr. <b>ON</b> o'rtacha quti: kun va sana. <b>AT</b> eng kichik nuqta: aniq soat. Kattadan kichikka: in 2026, in May, on Monday, on 5 May, at 7 o'clock.",
f:{p:"a:in|o:yil, oy, fasl, kun qismi (in the morning)",n:"a:on|o:hafta kuni, sana, bayram kuni",q:"a:at|o:soat, at night, at the weekend, at noon"},
use:[["In: uzun davr","{a:in} 2026, {a:in} summer, {a:in} the evening","2026 yilda, yozda, kechqurun"],["On: kun","{a:on} Friday, {a:on} 1 September, {a:on} my birthday","juma kuni, 1 sentabrda, tug'ilgan kunimda"],["At: aniq nuqta","{a:at} 5 o'clock, {a:at} night, {a:at} lunchtime","soat 5 da, tunda, tushlik payti"],["Predlogsiz: last, next, this, every","I saw him last week.","Uni o'tgan hafta ko'rdim."],["For davomiylik, since boshlanish, ago qancha oldin","for two years, since 2020, two days ago","ikki yil davomida, 2020 dan beri, ikki kun oldin"]],
err:[["I was born in 5 May.","I was born on 5 May.","Sana bilan on."],["See you on next Monday.","See you next Monday.","Next oldidan predlog yo'q."],["I get up in 7 o'clock.","I get up at 7 o'clock.","Soat bilan at."]],
ex:[["mc","The lesson starts ___ 9 o'clock.",["in","on","at"],2,"Soat: at."],
["mc","My birthday is ___ July.",["in","on","at"],0,"Oy: in."],
["mc","We have a meeting ___ Monday.",["in","on","at"],1,"Hafta kuni: on."],
["mc","I usually study ___ night.",["in","on","at"],2,"At night."],
["mc","She moved here three years ___.",["for","since","ago"],2,"Qancha oldin: ago."],
["in","He was born ___ 1999.",["in"],"Yil: in."]]},

{id:"prep-place",line:"prep",t:"Joy va harakat predloglari",s:"Qayerda va qayerga",
idea:"Yana uch o'lcham. <b>IN</b> ichida, atrofi o'ralgan: in a box, in the room, in Andijan. <b>ON</b> sirt ustida, tegib turadi: on the table, on the wall. <b>AT</b> nuqta, manzil: at the door, at the bus stop, at school. Harakat bo'lsa, yo'nalish predloglari kerak: <b>to</b> (...ga), <b>into</b> (ichiga), <b>from</b> (...dan).",
f:{p:"a:in|o:ichida: in the bag, in the city, in bed",n:"a:on|o:ustida: on the floor, on the bus, on the left",q:"a:at|o:nuqta: at home, at work, at the station"},
use:[["In: ichida","The keys are {a:in} my bag.","Kalitlar sumkamda."],["On: sirtida","The picture is {a:on} the wall.","Rasm devorda."],["At: nuqtada","I'll meet you {a:at} the bus stop.","Sizni bekatda kutib olaman."],["Harakat: to, into, from","She went {a:to} school. He came {a:from} work.","U maktabga ketdi. U ishdan keldi."],["Boshqa joy predloglari","under, next to, between, behind, in front of, opposite","tagida, yonida, orasida, orqasida, oldida, qarshisida"]],
err:[["I am in home.","I am at home.","At home."],["She went in school.","She went to school.","Harakat yo'nalishi: to."],["He arrived to London.","He arrived in London.","Arrive in (shahar), arrive at (bino)."]],
ex:[["mc","There is a clock ___ the wall.",["in","on","at"],1,"Sirtda: on."],
["mc","She lives ___ Fergana.",["in","on","at"],0,"Shahar ichida: in."],
["mc","I left my phone ___ home.",["in","on","at"],2,"At home."],
["mc","We go ___ university by bus.",["in","at","to"],2,"Yo'nalish: to."],
["mc","The bank is ___ the post office and the cafe.",["between","under","into"],0,"Ikki narsa orasida: between."],
["in","The cat is sleeping ___ the bed (tagida).",["under"],"Tagida: under."]]},

/* ---------- M14 MURAKKAB GAPLAR ---------- */
{id:"relative",line:"cmplx",t:"Relative clauses",s:"Who, which, that, whose, where",
idea:"Ikki qisqa gapni bitta uzun gapga ulash mumkin: “Bu o'sha odam. U menga yordam berdi.” → “Bu menga yordam bergan odam.” Ulaydigan so'z nima haqida gapirayotganingizga bog'liq: <b>odam</b> bo'lsa <b>who</b>, <b>narsa</b> bo'lsa <b>which</b>, ikkalasi uchun ham <b>that</b>, egalik bo'lsa <b>whose</b>, joy bo'lsa <b>where</b>.",
f:{p:"o:odam +|a:who / that|o:+ gap",n:"o:narsa +|a:which / that|o:+ gap",q:"o:joy +|a:where|o:/ egalik +|a:whose"},
use:[["Odam: who","The man {a:who} lives next door is a doctor.","Qo'shni uyda yashaydigan odam shifokor."],["Narsa: which / that","The book {a:which} I bought is interesting.","Men sotib olgan kitob qiziqarli."],["Egalik: whose","The girl {a:whose} father is a pilot.","Otasi uchuvchi bo'lgan qiz."],["Joy: where","The town {a:where} I was born.","Men tug'ilgan shahar."],["To'ldiruvchi bo'lsa tushirib qoldirish mumkin","The film (that) we watched was great.","Biz ko'rgan film zo'r edi."]],
err:[["The man which called you is here.","The man who called you is here.","Odam uchun who."],["The book who I read was good.","The book which I read was good.","Narsa uchun which / that."],["The man who he lives here is kind.","The man who lives here is kind.","Who o'zi ega, he ortiqcha."]],
ex:[["mc","The woman ___ teaches us is from London.",["which","who","whose"],1,"Odam: who."],
["mc","This is the phone ___ I bought yesterday.",["who","which","where"],1,"Narsa: which."],
["mc","That's the boy ___ bike was stolen.",["who","whose","which"],1,"Egalik: whose."],
["mc","This is the house ___ I grew up.",["which","where","who"],1,"Joy: where."],
["ord","The film that we watched was very long","Biz ko'rgan film juda uzun edi."],
["mc","Qaysi gapda that ni tushirib qoldirish mumkin?",["The man that called me is my boss.","The cake that you made was delicious.","The dog that bit me ran away."],1,"That to'ldiruvchi bo'lganda (you made that) tushiriladi."]]},

{id:"linkers",line:"cmplx",t:"Bog'lovchilar",s:"Gaplarni ulash",
idea:"Bog'lovchilar gaplar orasidagi <b>yo'l belgilari</b>: ular keyingi fikr qaysi tomonga burilishini ko'rsatadi. Qo'shish: <b>and</b>. Qarama-qarshi: <b>but, although, however</b>. Sabab: <b>because</b>. Natija: <b>so</b>. Maqsad: <b>to, so that</b>. Belgini to'g'ri tanlasangiz, tinglovchi adashmaydi.",
f:{p:"a:because|o:+ sabab     |a:so|o:+ natija",n:"a:although|o:+ gap     |a:despite / in spite of|o:+ ot yoki V-ing",q:"a:however|o:yangi gap boshida, vergul bilan"},
use:[["Sabab","I stayed home {a:because} it was raining.","Yomg'ir yog'ayotgani uchun uyda qoldim."],["Natija","It was raining, {a:so} I stayed home.","Yomg'ir yog'ayotgan edi, shuning uchun uyda qoldim."],["Zidlik: although + gap","{a:Although} it was cold, we went out.","Sovuq bo'lsa ham, tashqariga chiqdik."],["Zidlik: despite + ot","{a:Despite} the cold, we went out.","Sovuqqa qaramay, tashqariga chiqdik."],["Maqsad","I study hard {a:to} pass the exam.","Imtihondan o'tish uchun qattiq o'qiyman."]],
err:[["Although it was late, but we continued.","Although it was late, we continued.","Although va but birga kelmaydi."],["Despite it was raining, we played.","Although it was raining, we played.","Despite dan keyin gap emas, ot keladi."],["Because of I was ill, I stayed home.","Because I was ill, I stayed home.","Because of dan keyin ot keladi."]],
ex:[["mc","I was tired, ___ I went to bed early.",["because","so","although"],1,"Natija: so."],
["mc","___ he is rich, he is not happy.",["Because","Although","Despite"],1,"Zidlik + gap: although."],
["mc","We didn't go out ___ the rain.",["because","because of","although"],1,"Ot oldidan: because of."],
["mc","___ the bad weather, the match continued.",["Although","Despite","However"],1,"Ot oldidan: despite."],
["mc","She went to the shop ___ some bread.",["for buy","to buy","for buying"],1,"Maqsad: to + V1."],
["ord","Although she was tired, she finished the work","Charchagan bo'lsa ham, u ishni tugatdi."]]}
);

